from collections import deque

def is_l_tromino(board, n, r, c):
    # Checks if an L-tromino exists anchored at (r, c) in the specified fixed orientation.
    # Standard L-tromino pattern (assuming cells are (r,c), (r+1, c), (r, c+1))
    # Since rotations are not allowed, we check the single fixed pattern:
    # (r, c), (r+1, c), (r, c+1)
    if r + 1 < n and c + 1 < n:
        return board[r][c] == 0 and board[r+1][c] == 0 and board[r][c+1] == 0
    return False

def find_l_trominos(board, n):
    # Checks for the fixed L-shape: (r, c), (r+1, c), (r, c+1)
    trominos = []
    for r in range(n - 1):
        for c in range(n - 1):
            if is_l_tromino(board, n, r, c):
                trominos.append([(r, c), (r+1, c), (r, c+1)])
    return trominos

